from taf.gnb.oam.coam.vdu.releases.vduoam24r3 import vDuOAM24R3
from taf.gnb.oam.coam.vdu.schemas.fh.get_real_time_measurements_info import (
    RealTimeMeasurementsInfo,
)
from taf.gnb.oam.coam.vdu.schemas.asm.get_rmods_status import RmodsStatus


class vDuOAM25R1(vDuOAM24R3):
    def get_rmods_status(self, timeout=30, raw=False):
        response = self.asm_v1.get_rmods_status(timeout=timeout, raw=raw)
        return response if raw else RmodsStatus.from_object_dict(response)

    def start_5g_uplink_ccm_test_prach(self, nrcell_id, interval, beam_pattern_id, receiving_slot,
                                       expectation_slot, preamble_index, accepted_timing_error,
                                       constant_offset, delay_pattern_single_step_duration,
                                       ru_mode, phys_cell_id, prach_configuration_index, pfa_target_prach_id,
                                       prach_root_sequence_index, nrarfcn, zero_correlation_zone_config,
                                       timeout=60, nrarfcn_ul=None, nrarfcn_dl=None, prach_sequence_type=None,
                                       act_prach_format_c2_with_scs=False):
        return self.cp_config.start_5g_uplink_ccm_test_prach(
            nrcell_id=nrcell_id,
            interval=interval,
            beam_pattern_id=beam_pattern_id,
            receiving_slot=receiving_slot,
            expectation_slot=expectation_slot,
            preamble_index=preamble_index,
            accepted_timing_error=accepted_timing_error,
            constant_offset=constant_offset,
            delay_pattern_single_step_duration=delay_pattern_single_step_duration,
            ru_mode=ru_mode,
            phys_cell_id=phys_cell_id,
            prach_configuration_index=prach_configuration_index,
            pfa_target_prach_id=pfa_target_prach_id,
            prach_root_sequence_index=prach_root_sequence_index,
            nrarfcn=nrarfcn,
            zero_correlation_zone_config=zero_correlation_zone_config,
            nrarfcn_ul=nrarfcn_ul,
            nrarfcn_dl=nrarfcn_dl,
            prach_sequence_type=prach_sequence_type,
            timeout=timeout,
            act_prach_format_c2_with_scs=act_prach_format_c2_with_scs)

    def get_real_time_measurements(self, rmods_runtime_distnames=None, start_time=None, timeout=30):
        return self.fh_licensed_v1.get_real_time_measurements(rmods_runtime_distnames=rmods_runtime_distnames,
                                                              start_time=start_time,
                                                              timeout=timeout)

    def get_real_time_measurements_info(self, timeout=30, raw=False):
        response = self.fh_v1.get_real_time_measurements_info(timeout=timeout)
        return response if raw else RealTimeMeasurementsInfo.from_object_dict(response)

    def get_account_status_report(self, timeout=30):
        return self.asm_v1.get_account_status_report(timeout=timeout)

    def change_local_account_state(self, account_type, enable, timeout=30):
        return self.asm_v1.change_local_account_state(account_type=account_type, enable=enable, timeout=timeout)

    def collect_screl(self, directory, coverage, screl_type, compressed, timeout=600):
        return self.asm_licensed_v1.collect_screl(directory=directory, coverage=coverage, screl_type=screl_type,
                                                  compressed=compressed, timeout=timeout)

    def trigger_screl_collection(self, coverage, screl_type, timeout=30):
        return self.asm_licensed_v1.trigger_screl_collection(coverage=coverage, screl_type=screl_type, timeout=timeout)

    def get_screl_operation_info(self, operation_id, timeout=30):
        return self.asm_licensed_v1.get_screl_operation_info(operation_id=operation_id, timeout=timeout)

    def delete_screl_collection_operation(self, operation_id, timeout=30):
        return self.asm_licensed_v1.delete_screl_collection_operation(operation_id=operation_id, timeout=timeout)

    def download_screl_files(self, operation_id, files_list, directory, compressed, timeout=30):
        return self.asm_licensed_v1.download_screl_files(operation_id=operation_id, files_list=files_list, directory=directory,
                                                         compressed=compressed, timeout=timeout)

    def get_screl_history_file(self, directory, timeout=30):
        return self.asm_licensed_v1.get_screl_history_file(directory=directory, timeout=timeout)

    def synchronize_to_ran_nics(self, timeout=30):
        return self.asm_v1.synchronize_to_ran_nics(timeout=timeout)

    def get_rmod_measurements_by_id(self, rmod_id, limit_to=None, timeout=60):
        return self.fh_licensed_v1.get_rmod_measurements_by_id(rmod_id=rmod_id, limit_to=limit_to, timeout=timeout)

    def update_interface_mirroring_configuration(self, usage_state, interface='L1-L2', nr_cell_dns=None, mirroring_time=0,
                                                 timeout=30):
        return self.asm_licensed_v1.update_interface_mirroring_configuration(usage_state=usage_state,
                                                                             interface=interface,
                                                                             nr_cell_dns=nr_cell_dns,
                                                                             mirroring_time=mirroring_time,
                                                                             timeout=timeout)

    def get_interface_mirroring_information(self, timeout=30):
        return self.asm_licensed_v1.get_interface_mirroring_information(timeout=timeout)
